def generate_permutations(s):
    '''Return a list of all permutations of the input string.'''
    if len(s) == 1:
        return [s]
    perms = []
    for i in range(len(s)):
        for perm in generate_permutations(s[:i] + s[i+1:]):
            perms.append(s[i] + perm)
    return perms
